def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (ignore it)
        if '+' in version:
            version = version[:version.index('+')]

        # Split pre-release
        if '-' in version:
            core, prerelease = version.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = version
            prerelease_parts = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Convert prerelease parts to comparable format
        if prerelease_parts is not None:
            prerelease_tuple = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_tuple.append((0, int(part)))
                else:
                    prerelease_tuple.append((1, part))
            prerelease_key = (0, tuple(prerelease_tuple))
        else:
            prerelease_key = (1,)

        return (major, minor, patch, prerelease_key)

    return sorted(versions, key=parse_version)

